#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> arr(n);
    long long sum = 0, low = LLONG_MIN;

    for (long long &x : arr) {
        cin >> x;
        sum += x;
        low = max(low, x);
    }

    long long high = max(low, 2 * low + 2);

    auto check = [&](long long k) {
        return k >= low && (__int128)n * k > (__int128)2 * sum;
    };

    while (!check(high)) {
        high = high * 2 + 1;
    }

    while (low < high) {
        long long mid = low + (high - low) / 2;
        if (check(mid))
            high = mid;
        else
            low = mid + 1;
    }

    cout << low << '\n';
    return 0;
}

